// #include "sdf/sdfs_2d.glsl"

// iMouse
// iResolution

#define NUM_SDFS 20
#define INF 1./0.

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    // mod to handle aspect ratio based on a suggetion by spalmer (https://www.shadertoy.com/user/spalmer)
    // map y to [-1.,1.] and x to [-1,1] * res.x/res.y
    vec2 st = (fragCoord.xy * 2. - iResolution.xy) / iResolution.y;

    float sdf_scale = 0.08 + (sin(iTime*1.1)*0.01);
    float brightness = 1.;

    vec3 in_color = vec3(0.9333, 0.5569, 0.0627);
    vec3 out_color = vec3(0.253,0.431,0.810);

    vec2 circ_center = vec2(0.5);
    float circ_radius = 0.4 * 0.8;

    vec2 rect_center = vec2(0.);
    vec2 rect_hw = vec2(0.5, .7)*0.8;


    float sdfs_add[NUM_SDFS];
    float sdfs_sub[NUM_SDFS];
    for(int i = 0; i < NUM_SDFS; i++){
        sdfs_add[i] = INF;
        sdfs_sub[i] = INF;
    }

    sdfs_add[0] = circle_sdf(st,circ_radius, circ_center);
    sdfs_add[1] = circle_sdf(st,circ_radius, circ_center-vec2(1.,0.));
    sdfs_add[2] = square_sdf(st,rect_hw, rect_center);

    sdfs_sub[0] = circle_sdf(st,circ_radius*0.2, circ_center);
    sdfs_sub[1] = circle_sdf(st,circ_radius*0.2, circ_center-vec2(1.,0.));
    sdfs_sub[3] = square_sdf(st,rect_hw.yx*0.2, rect_center - vec2(0.,0.3));


    float out_sdf = INF;
    for(int i = 0; i < sdfs_add.length(); i++){
        out_sdf = union_sdf_cubic(out_sdf, sdfs_add[i], 0.03);
    }

    for(int i = 0; i < sdfs_sub.length(); i++){
        out_sdf = sub_sdf_cubic(out_sdf, sdfs_sub[i], 0.01);
    }


    // vec3 shader_color = sdf_quant_shader(out_sdf, sdf_scale, in_color, out_color);
    vec3 shader_color = sdf_quant_shader(out_sdf, sdf_scale, in_color, out_color);
  	vec3 color = brightness * shader_color;

  fragColor = vec4(color,1.);

}

vec3 sdf_quant_shader(in float sdf, in float sdf_scale, in vec3 in_color, in vec3 out_color){

    sdf = sign(sdf) * mod(abs(sdf),sdf_scale) / sdf_scale;

    return step(0.0, sdf) * sdf * out_color +
        (1. - step(0.0, sdf)) * -sdf * in_color;

}

// cubic polynomial
float union_sdf_cubic( float a, float b, float k )
{
    if (a == 1./0. || b == 1./0.){
        return min(a,b);

    }
    k *= 6.0;
    float x = (b-a)/k;
    float g = (x> 1.0) ? x :
              (x<-1.0) ? 0.0 :
              (1.0+3.0*x*(x+1.0)-abs(x*x*x))/6.0;
    return b - k * g;
}

float sub_sdf_cubic( float a, float b, float k )
{
    b = -b;
    if (a == 1./0. || b == 1./0.){

    }
    // k *= 6.0;
    float x = (a-b)/k;
    float interp = (1.0+3.0*x*(x+1.0)-abs(x*x*x))/6.0;
    float g = (x> 1.0) ? a/k:
              (x<-1.0) ? b/k:
              mix(b/k,a/k,interp);
    return k * g;
}



float circle_sdf(in vec2 st, in float radius, in vec2 center){
    vec2 dist = st - center;
    return length(dist) - radius;
}

float square_sdf(in vec2 st, in vec2 hw, in vec2 center){
    // vec2 dist = st - center;
    vec2 dist = abs(st - center) - hw;


    return length(max(dist, 0.)) + min(max(dist.x,dist.y),0.0);
}
